starter_code.C:
#include <stdio.h>
int main(void) {
    int number;
    if (scanf("%d", &number) != 1) return 0;
    if (number > 0) printf("Positive\n");
    else if (number < 0) printf("Negative\n");
    else printf("Zero\n");
    return 0;
}

